<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Archive, Edit3, Plus, RotateCcw, Save, Search, Trash2, Truck, X } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import { suppliersApi, type SupplierPayload, type SupplierRecord } from '../api/suppliers'
import { formatDateTime } from '../utils/date'
const emit=defineEmits<{notify:[string]}>();type Filter='Active'|'Archived'|'All';const rows=ref<SupplierRecord[]>([]);const selected=ref<string|null>(null);const filter=ref<Filter>('Active');const search=ref('');const editing=ref(false);const form=ref<SupplierPayload>(empty());const error=ref('');const loading=ref(false)
const current=computed(()=>rows.value.find(v=>v.id===selected.value)??null);const filtered=computed(()=>rows.value.filter(v=>(filter.value==='All'||(filter.value==='Active'?v.active:!v.active))&&(!search.value||[v.name,v.code,v.phone,v.email].join(' ').toLowerCase().includes(search.value.toLowerCase()))));
onMounted(load);function empty():SupplierPayload{return{name:'',code:'',phone:'',email:'',address:'',notes:''}};async function load(){loading.value=true;try{rows.value=await suppliersApi.list(true);if(!selected.value&&rows.value[0])selected.value=rows.value[0].id}catch(e){error.value=String(e)}finally{loading.value=false}};function startCreate(){selected.value=null;form.value=empty();editing.value=true};function startEdit(){if(!current.value)return;form.value={name:current.value.name,code:current.value.code,phone:current.value.phone,email:current.value.email,address:current.value.address,notes:current.value.notes};editing.value=true};async function save(){try{const v=editing.value&&selected.value?await suppliersApi.update(selected.value,form.value):await suppliersApi.create(form.value) as unknown as SupplierRecord;rows.value=rows.value.some(x=>x.id===v.id)?rows.value.map(x=>x.id===v.id?v:x):[v,...rows.value];selected.value=v.id;editing.value=false;emit('notify','Supplier saved.')}catch(e){error.value=String(e)}};async function setActive(active:boolean){if(!current.value)return;try{const v=active?await suppliersApi.reactivate(current.value.id):await suppliersApi.archive(current.value.id);rows.value=rows.value.map(x=>x.id===v.id?v:x);emit('notify',active?'Supplier reactivated.':'Supplier archived.')}catch(e){error.value=String(e)}};async function remove(){if(!current.value||!window.confirm('Delete this supplier permanently?'))return;try{await suppliersApi.remove(current.value.id);rows.value=rows.value.filter(x=>x.id!==current.value!.id);selected.value=null;emit('notify','Supplier deleted.')}catch(e){error.value=String(e)}}
</script>
<template><div class="suppliers-view"><WorkspaceStickyStack><header class="workspace-heading"><div><p class="eyebrow">Catalog / purchasing</p><h1>Suppliers</h1><p class="heading-description">Keep supplier contacts and purchasing history safe and readable.</p></div><button class="button button-primary" @click="startCreate"><Plus :size="16"/> New supplier</button></header><section class="suppliers-filter panel"><label class="materials-search"><Search :size="16"/><input v-model="search" type="search" placeholder="Search suppliers"/></label><label class="filter-control"><span>Status</span><select v-model="filter"><option>Active</option><option>Archived</option><option>All</option></select></label><span>{{ filtered.length }} shown</span></section></WorkspaceStickyStack><div v-if="error" class="form-error" role="alert">{{ error }} <button class="icon-button" @click="error=''" aria-label="Dismiss"><X :size="14"/></button></div><section class="suppliers-layout"><SectionPanel title="Supplier register" subtitle="Select a supplier to inspect or edit."><div v-if="loading" class="materials-empty">Loading suppliers…</div><div v-else-if="filtered.length" class="table-wrap"><table class="data-table"><thead><tr><th>Supplier</th><th>Contact</th><th>Status</th><th>Updated</th></tr></thead><tbody><tr v-for="v in filtered" :key="v.id" :class="{'is-selected':selected===v.id}" @click="selected=v.id"><td><span class="table-primary">{{v.name}}</span><span class="table-secondary">{{v.code||'No code'}}</span></td><td>{{v.phone||v.email||'—'}}</td><td><StatusBadge :label="v.active?'Active':'Archived'" :tone="v.active?'green':'slate'"/></td><td>{{formatDateTime(v.updatedAt)}}</td></tr></tbody></table></div><div v-else class="materials-empty"><Truck :size="22"/><p>No suppliers found.</p></div></SectionPanel><SectionPanel v-if="editing" title="Supplier editor" subtitle="Persisted in the local database."><form class="supplier-form" @submit.prevent="save"><label class="form-field"><span>Name</span><input v-model="form.name" required /></label><div class="material-form-grid"><label class="form-field"><span>Code</span><input v-model="form.code" /></label><label class="form-field"><span>Phone</span><input v-model="form.phone" /></label></div><label class="form-field"><span>Email</span><input v-model="form.email" type="email" /></label><label class="form-field"><span>Address</span><textarea v-model="form.address" rows="2"/></label><label class="form-field"><span>Notes</span><textarea v-model="form.notes" rows="3"/></label><div class="material-form-actions"><button class="button button-secondary" type="button" @click="editing=false">Cancel</button><button class="button button-primary"><Save :size="15"/> Save</button></div></form></SectionPanel><SectionPanel v-else-if="current" title="Supplier inspector" subtitle="Archive and delete have different meanings."><div class="inspector-heading"><div class="material-inspector-icon"><Truck :size="19"/></div><div><h3>{{current.name}}</h3><p>{{current.code||'No code'}}</p></div></div><div class="inspector-status"><StatusBadge :label="current.active?'Active':'Archived'" :tone="current.active?'green':'slate'"/></div><dl class="inspector-details"><div><dt>Phone</dt><dd>{{current.phone||'—'}}</dd></div><div><dt>Email</dt><dd>{{current.email||'—'}}</dd></div><div><dt>Address</dt><dd>{{current.address||'—'}}</dd></div><div><dt>Updated</dt><dd>{{formatDateTime(current.updatedAt)}}</dd></div></dl><div class="inspector-actions"><button class="button button-secondary" @click="startEdit"><Edit3 :size="15"/> Edit</button><button class="button button-secondary" @click="setActive(!current.active)"><RotateCcw v-if="!current.active" :size="15"/><Archive v-else :size="15"/> {{current.active?'Archive':'Reactivate'}}</button><button class="button button-danger" @click="remove"><Trash2 :size="15"/> Delete</button></div></SectionPanel><SectionPanel v-else title="Supplier inspector" subtitle="Select a row to inspect it."><div class="inspector-empty-copy"><Truck :size="20"/><p>Supplier details will appear here.</p></div></SectionPanel></section></div></template>
